def dp_count(n, l, c, d, r, modulus):
    if n < 0:
        return 0
    dp = [0] * (n + 1)
    dp[0] = 1
    for m in range(1, n + 1):
        allowed_colored = (m % d == r)
        allowed_noncolored = (m % l != 0)
        # base = sum_{t>=0} dp_prev[i - t*m] via in-place coin-change update
        base = dp[:]  # start from dp_prev
        for i in range(m, n + 1):
            base[i] = (base[i] + base[i - m]) % modulus
        # add = sum_{t>=1} dp_prev[i - t*m] = base - dp_prev
        add = [0] * (n + 1)
        for i in range(0, n + 1):
            add[i] = (base[i] - dp[i]) % modulus
        if allowed_colored and allowed_noncolored:
            # factor: (1 + c*q^m)/(1 - q^m) = base + (c - 1)*add
            new_dp = [0] * (n + 1)
            for i in range(0, n + 1):
                new_dp[i] = (base[i] + (c - 1) * add[i]) % modulus
            dp = new_dp
        elif allowed_colored and not allowed_noncolored:
            # factor: 1 + c*q^m/(1 - q^m) = dp_prev + c*add
            new_dp = [0] * (n + 1)
            for i in range(0, n + 1):
                new_dp[i] = (dp[i] + c * add[i]) % modulus
            dp = new_dp
        elif (not allowed_colored) and allowed_noncolored:
            # factor: 1/(1 - q^m) = base
            dp = base
        else:
            # neither allowed: factor = 1 (do nothing)
            pass
    return dp[n] % modulus

